<section class="page-heading"><div><h1>Import products</h1><p>Preview first. Each accepted product gets its own atomic opening-stock entry.</p></div><a class="button" href="<?= e(url('/products')) ?>">Products</a></section>
<?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<section class="surface product-section"><h2>1. Upload CSV or Excel (.xlsx)</h2><p class="subtle-text">Maximum 5 MB / 1,000 rows. Use ISO dates (YYYY-MM-DD), plain numbers and existing category/brand/tax names. Unknown names are rejected, never created automatically. Blank SKU generates a new one. Bike mappings use the separate compatibility template and import mode below. Unknown names are rejected; new mappings stay unverified.</p><a class="button" href="<?= e(url('/products/template')) ?>">Download product template</a> <a class="button" href="<?= e(url('/products/template')) ?>&amp;kind=compatibility">Download compatibility template</a><form method="post" action="<?= e(url('/products/import-preview')) ?>" enctype="multipart/form-data" class="product-actions"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><label>Import type<select name="kind"><option value="products">New products and opening stock</option><option value="compatibility">Compatibility for existing SKUs (no stock changes)</option></select></label><label>File<input type="file" name="file" accept=".csv,.xlsx" required></label><button class="button button-primary">Preview import</button></form></section>
<?php if($stage): ?><?php $results=$stage['results'];$rows=$results??$stage['rows'];$failed=count(array_filter($rows,fn($r)=>(bool)$r['errors']));$success=count($rows)-$failed;$warnings=(bool)array_filter($stage['rows'],fn($r)=>(bool)$r['warnings']); ?>
<section class="surface product-section"><h2><?= $results===null?'2. Review rows':'Import results' ?></h2><p><?= $results===null?'Valid':'Successful' ?>: <strong><?= $success ?></strong> · <?= $results===null?'Invalid':'Failed' ?>: <strong><?= $failed ?></strong></p><a class="button" href="<?= e(url('/products/import-report')) ?>&amp;token=<?= e($token) ?>">Download row report</a><?php if($results===null): ?><form method="post" action="<?= e(url('/products/import-commit')) ?>" class="import-confirm"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="token" value="<?= e($token) ?>"><?php if($warnings): ?><label class="check-label"><input type="checkbox" name="confirm_duplicates" value="1" required> I reviewed the possible duplicate warnings and confirm these are distinct physical products.</label><?php endif; ?><p class="subtle-text">Invalid rows are reported below and will not be saved. Valid rows are revalidated when imported. Resubmitting this preview will not duplicate accepted products or stock.</p><button class="button button-primary" <?= $success===0?'disabled':'' ?>>Import <?= $success ?> valid rows</button></form><?php endif; ?></section>
<div class="surface table-scroll"><table><thead><tr><th>Row</th><th>Product</th><th>Status</th><th>Validation / warnings</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= (int)$r['row'] ?></td><td><?= e($r['name']) ?></td><td><?= $r['errors']?'Rejected':($results===null?'Ready':'Imported') ?><?php if(!empty($r['id'])): ?> <a href="<?= e(url('/products/view')) ?>&amp;id=<?= (int)$r['id'] ?>">View</a><?php endif; ?></td><td class="import-messages"><?php foreach([...$r['errors'],...($r['warnings']??[])] as $message): ?><div><?= e($message) ?></div><?php endforeach; ?><?php if($results===null && !$r['errors'] && ($stage['kind']??'products')==='products'): ?><small><?= e($r['data']['category']??'') ?> · <?= e($r['data']['brand']??'No brand') ?> · Opening <?= e((string)($r['data']['opening_quantity']??0)) ?> · Selling <?= e((string)$r['data']['selling_price']) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
